$msgText = Decode-Base64Text $commitMsg_b64
[System.IO.File]::WriteAllText($msgFile, $msgText, $utf8NoBom)

$hasChanges = git status --porcelain
if ($hasChanges) {
    git commit -F $msgFile
    git push
    Write-Host ""
    Write-Host (Decode-Base64Text $done_pushed_b64)
} else {
    Write-Host ""
    Write-Host (Decode-Base64Text $no_changes_b64)
}

Remove-Item $msgFile -Force -ErrorAction SilentlyContinue

Write-Host ""
Write-Host (Decode-Base64Text $self_delete_b64)
Start-Sleep -Seconds 1
Remove-Item -Path $PSCommandPath -Force
